### 1. Código Rust

Este código destina-se a realizar downloads e emitir eventos conforme o progresso.

```rust
use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};
use tauri::{AppHandle, ipc::Channel};
use reqwest::Client;
use tokio::{fs as tokio_fs, io::AsyncWriteExt};
use std::time::Instant;

#[derive(Debug, Deserialize)]
struct PatchEntry {
    file_name: String,
}

#[derive(Clone, Debug, Serialize)]
#[serde(rename_all = "camelCase", tag = "event", content = "data")]
enum DownloadEvent<'a> {
    #[serde(rename_all = "camelCase")]
    Started {
        url: &'a str,
        download_id: usize,
        content_length: usize,
    },
    #[serde(rename_all = "camelCase")]
    Progress {
        download_id: usize,
        downloaded_bytes: u64,
    },
    #[serde(rename_all = "camelCase")]
    Finished {
        download_id: usize,
    },
}

fn get_exe_dir() -> PathBuf {
    std::env::current_exe().unwrap().parent().unwrap().to_path_buf()
}

// Função para ler o arquivo patch
async fn read_patch_file(path: &Path) -> Result<Vec<PatchEntry>, Box<dyn std::error::Error>> {
    let content = tokio_fs::read_to_string(path).await?;
    let patches: Vec<PatchEntry> = serde_json::from_str(&content)?;
    Ok(patches)
}

async fn download_file(
    app_handle: &AppHandle,
    client: &Client,
    entry: PatchEntry,
    download_dir: &Path,
    current_file: usize,
    total_files: usize,
    on_event: &Channel<DownloadEvent<'static>>,
) -> Result<(), Box<dyn std::error::Error>> {
    let url = format!("https://hil-speed.hetzner.com/{}", entry.file_name);
    let file_path = download_dir.join(&entry.file_name);

    let mut response = client.get(&url).send().await?;
    let total_bytes = response.content_length().unwrap_or(0);
    let mut file = tokio_fs::OpenOptions::new()
        .write(true)
        .create(true)
        .open(file_path)
        .await?;

    let mut downloaded_bytes = 0;

    // Emitindo evento de início
    on_event.send(DownloadEvent::Started {
        url: &url,
        download_id: 1,
        content_length: total_bytes as usize,
    }).unwrap();

    while let Some(chunk) = response.chunk().await? {
        file.write_all(&chunk).await?;
        downloaded_bytes += chunk.len() as u64;

        // Emitindo evento de progresso
        on_event.send(DownloadEvent::Progress {
            download_id: 1,
            downloaded_bytes,
        }).unwrap();
    }

    // Emitindo evento de finalização
    on_event.send(DownloadEvent::Finished {
        download_id: 1,
    }).unwrap();

    Ok(())
}

#[tauri::command]
pub async fn start_downloads(app_handle: AppHandle, on_event: Channel<DownloadEvent<'static>>) -> Result<(), String> {
    let exe_dir = get_exe_dir();
    let patch_file_path = exe_dir.join("patch.json");
    let download_dir = exe_dir.join("patchs");

    if !download_dir.exists() {
        tokio_fs::create_dir_all(&download_dir).await.map_err(|e| e.to_string())?;
    }

    let patches = read_patch_file(&patch_file_path).await.map_err(|e| e.to_string())?;
    let client = Client::new();
    let total_files = patches.len();

    // Conectando ao servidor e emitindo mensagens
    on_event.send(DownloadEvent::Started {
        url: "https://hil-speed.hetzner.com/",
        download_id: 1,
        content_length: total_files,
    }).unwrap();

    for (current_file, entry) in patches.into_iter().enumerate() {
        if let Err(err) = download_file(&app_handle, &client, entry, &download_dir, current_file + 1, total_files, &on_event).await {
            eprintln!("Erro ao baixar arquivo: {}", err);
        }
    }

    return Ok(());
}
```

