        download_id: 1,
        content_length: total_bytes as usize,
    }).unwrap();

    while let Some(chunk) = response.chunk().await? {
        file.write_all(&chunk).await?;
        downloaded_bytes += chunk.len() as u64;

        // Emitindo evento de progresso
        on_event.send(DownloadEvent::Progress {
            download_id: 1,
            downloaded_bytes,
        }).unwrap();
    }

    // Emitindo evento de finalização
    on_event.send(DownloadEvent::Finished {
        download_id: 1,
    }).unwrap();

    Ok(())
}

#[tauri::command]
pub async fn start_downloads(app_handle: AppHandle, on_event: Channel<DownloadEvent<'static>>) -> Result<(), String> {
    let exe_dir = get_exe_dir();
    let patch_file_path = exe_dir.join("patch.json");
    let download_dir = exe_dir.join("patchs");

    if !download_dir.exists() {
        tokio_fs::create_dir_all(&download_dir).await.map_err(|e| e.to_string())?;
    }

    let patches = read_patch_file(&patch_file_path).await.map_err(|e| e.to_string())?;
    let client = Client::new();
    let total_files = patches.len();

    // Conectando ao servidor e emitindo mensagens
    on_event.send(DownloadEvent::Started {
        url: "https://hil-speed.hetzner.com/",
        download_id: 1,
        content_length: total_files,
    }).unwrap();

    for (current_file, entry) in patches.into_iter().enumerate() {
        if let Err(err) = download_file(&app_handle, &client, entry, &download_dir, current_file + 1, total_files, &on_event).await {
            eprintln!("Erro ao baixar arquivo: {}", err);
        }
    }

    return Ok(());
}
